/*  СГЕНЕРИРОВАНО scripts/gen-dark-theme.js — не править руками  */
/*  styles.css  */
html[data-theme="dark"] {
    --purple: var(--dk-acc);
    --purple-2: var(--dk-acc);
    --purple-bubble: var(--dk-acc);
    --blue-soft: var(--dk-blue-tint);
    --blue-soft-2: var(--dk-blue-soft);
    --ink: var(--dk-text);
    --muted: var(--dk-muted);
    --page-bg: #0c0a14;
    --footer-bg: var(--dk-ink-bg)
}
html[data-theme="dark"] body {
    background: var(--page-bg);
    color: var(--ink)
}
html[data-theme="dark"] .aimg:not(.is-ready) {
    background-color: var(--dk-chip);
    background-image: linear-gradient(
    100deg,
    rgba(255, 255, 255, 0) 22%,
    color-mix(in oklab, var(--dk-card) 72%, transparent) 50%,
    rgba(255, 255, 255, 0) 78%
  )
}
html[data-theme="dark"] .screen {
    background: var(--page-bg)
}
html[data-theme="dark"] .card {
    background: var(--dk-page)
}
html[data-theme="dark"] .card--plain {
    background: var(--dk-card)
}
html[data-theme="dark"] .card--plain:has(.reg-inner) {
    background: var(--dk-page)
}
html[data-theme="dark"] .screen .logo {
    background: url(/assets/reg/logo-purple.svg) left center / contain no-repeat
}
html[data-theme="dark"] .screen .hero-header .logo, html[data-theme="dark"] .screen .footer .logo {
    background-image: url(/assets/reg/logo-white.svg)
}
html[data-theme="dark"] .lang-selector {
    background: var(--dk-card);
    border: none;
    color: var(--ink);
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.16)
}
html[data-theme="dark"] .lang-selector--flag {
    box-shadow: none
}
html[data-theme="dark"] .lang-selector .chev {
    color: var(--muted)
}
html[data-theme="dark"] .hero-header .lang-selector, html[data-theme="dark"] .reg-header .lang-selector {
    box-shadow: none;
    color: var(--dk-text)
}
html[data-theme="dark"] .hero-header .lang-selector .chev, html[data-theme="dark"] .reg-header .lang-selector .chev {
    background: url(/assets/reg/chev.svg) center / 24px 24px no-repeat
}
html[data-theme="dark"] .lang-menu {
    background: var(--dk-card);
    box-shadow: 0 18px 44px rgba(0, 0, 0, 0.36);
    border: 1px solid var(--dk-line)
}
html[data-theme="dark"] .lang-option {
    border: none;
